// Solar Terminator — Geo, route: jsx
// Source: solar-terminator
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// ---- inlined from solarTerminator ----
// NOAA solar-position formulae, ported from the solar-calculator package the notebook
// required. Angles are degrees unless noted; `t` is Julian centuries since J2000.0.

const RAD = Math.PI / 180;
const DEG = 180 / Math.PI;

const century = (ms: number) => (ms - Date.UTC(2000, 0, 1, 12)) / 3.15576e12;

function meanLongitude(t: number): number {
  const l = (280.46646 + t * (36000.76983 + t * 0.0003032)) % 360;
  return l < 0 ? l + 360 : l;
}

const meanAnomaly = (t: number) => 357.52911 + t * (35999.05029 - 0.0001537 * t);

const eccentricity = (t: number) => 0.016708634 - t * (0.000042037 + 0.0000001267 * t);

function equationOfCenter(t: number): number {
  const m = meanAnomaly(t) * RAD;
  return (
    Math.sin(m) * (1.914602 - t * (0.004817 + 0.000014 * t)) +
    Math.sin(2 * m) * (0.019993 - 0.000101 * t) +
    Math.sin(3 * m) * 0.000289
  );
}

function apparentLongitude(t: number): number {
  const nutation = 0.00478 * Math.sin((125.04 - 1934.136 * t) * RAD);
  return meanLongitude(t) + equationOfCenter(t) - 0.00569 - nutation;
}

function obliquity(t: number): number {
  const mean = 23 + (26 + (21.448 - t * (46.815 + t * (0.00059 - t * 0.001813))) / 60) / 60;
  return mean + 0.00256 * Math.cos((125.04 - 1934.136 * t) * RAD);
}

function declination(t: number): number {
  return (
    Math.asin(Math.sin(obliquity(t) * RAD) * Math.sin(apparentLongitude(t) * RAD)) * DEG
  );
}

/** Apparent minus mean solar time, in minutes. 15 degrees of longitude per hour, so /4 gives degrees. */
function equationOfTime(t: number): number {
  const e = eccentricity(t);
  const m = meanAnomaly(t) * RAD;
  const l = meanLongitude(t) * RAD;
  const y = Math.tan((obliquity(t) * RAD) / 2) ** 2;
  return (
    (y * Math.sin(2 * l) -
      2 * e * Math.sin(m) +
      4 * e * y * Math.sin(m) * Math.cos(2 * l) -
      0.5 * y * y * Math.sin(4 * l) -
      1.25 * e * e * Math.sin(2 * m)) *
    DEG *
    4
  );
}

/** The [longitude, latitude] where the sun is directly overhead at the given UTC instant. */
function subsolarPoint(ms: number): [number, number] {
  const t = century(ms);
  const dayStart = new Date(ms).setUTCHours(0, 0, 0, 0);
  const solarNoonLongitude = ((dayStart - ms) / 864e5) * 360 - 180;
  const longitude = solarNoonLongitude - equationOfTime(t) / 4;
  return [((((longitude + 180) % 360) + 360) % 360) - 180, declination(t)];
}

const MARGIN = { top: 8, right: 8, bottom: 28, left: 8 };

// A fixed instant, never `new Date()`, so the terminator is identical on every load.
// June solstice 2026 at 21:00 UTC: the Arctic is in full daylight, the Antarctic in full night.
const INSTANT = Date.UTC(2026, 5, 21, 21, 0, 0);
const INSTANT_LABEL = '21 June 2026, 21:00 UTC';

const NIGHT = '#6f8fc4';

const sphere: d3.GeoSphere = { type: 'Sphere' };
const graticule = d3.geoGraticule10();

const formatLongitude = (v: number) => `${Math.abs(v).toFixed(1)}°${v < 0 ? 'W' : 'E'}`;
const formatLatitude = (v: number) => `${Math.abs(v).toFixed(1)}°${v < 0 ? 'S' : 'N'}`;

export default function SolarTerminator({ width }: { width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = Math.max(width - MARGIN.left - MARGIN.right, 0);
  const innerHeight = Math.max(height - MARGIN.top - MARGIN.bottom, 0);

  const shapes = useMemo(() => {
    const [sunLongitude, sunLatitude] = subsolarPoint(INSTANT);
    // Night is the hemisphere opposite the sun: a 90-degree cap on the antipode.
    const night = d3
      .geoCircle()
      .radius(90)
      .center([sunLongitude + 180, -sunLatitude])();

    const projection = d3.geoEqualEarth().fitSize([innerWidth, innerHeight], sphere);
    const path = d3.geoPath(projection);
    const sun = projection([sunLongitude, sunLatitude]);

    return {
      sphere: path(sphere) ?? undefined,
      graticule: path(graticule) ?? undefined,
      land: path(worldLand) ?? undefined,
      night: path(night) ?? undefined,
      sun: sun && Number.isFinite(sun[0]) && Number.isFinite(sun[1]) ? sun : null,
      // The subsolar reading only fits once the chart is wide enough to hold it.
      caption:
        innerWidth < 420
          ? `Night at ${INSTANT_LABEL}`
          : `Night at ${INSTANT_LABEL}. Sun overhead at ${formatLatitude(
              sunLatitude
            )}, ${formatLongitude(sunLongitude)}.`
    };
  }, [innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`World map shading the night hemisphere at ${INSTANT_LABEL}`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <path d={shapes.sphere} fill="none" stroke="var(--muted)" strokeWidth={1} />
        <path
          d={shapes.graticule}
          fill="none"
          stroke="var(--line)"
          strokeWidth={0.5}
          strokeOpacity={0.9}
        />
        <path d={shapes.land} fill="var(--accent)" fillOpacity={0.45} />
        <path
          d={shapes.night}
          fill={NIGHT}
          fillOpacity={0.3}
          stroke={NIGHT}
          strokeWidth={1}
          strokeOpacity={0.8}
        />
        {shapes.sun && (
          <g transform={`translate(${shapes.sun[0]},${shapes.sun[1]})`}>
            <circle r={7} fill="none" stroke="var(--accent)" strokeWidth={1} strokeOpacity={0.6} />
            <circle r={3} fill="var(--accent)" />
          </g>
        )}
      </g>
      <text x={MARGIN.left} y={height - 9} fill="var(--muted)" fontSize={11}>
        {shapes.caption}
      </text>
    </svg>
  );
}
